function checkForPrime(numbers) {
  // Loop through each number in the input array
  for (const num of numbers) {
    // Check if the number is greater than or equal to 2 (the first prime number)
    if (num >= 2) {
      // Mark the number as a possible prime candidate
      let isPrime = true;

      // Check if the number is divisible by any integer from 2 to its square root (inclusive)
      for (let i = 2; i * i <= num; i++) {
        if (num % i === 0) {
          // If divisible, the number is not prime; set `isPrime` to false and break the loop
          isPrime = false;
          break;
        }
      }

      // If the number is prime, print it to the console
      if (isPrime) {
        console.log(`The prime number found is ${num}.`);
      }
    }
  }
}

// Example usage:
const inputNumbers = [4, 11, 13, 17, 19];
checkForPrime(inputNumbers);
```

