// Function to find common elements without extra data structures
vector<int> findCommonElements(vector<int> &arr1, vector<int> &arr2) {
    // Create a list to store common elements
    vector<int> common_elements;

    // First loop to search for common elements in arr1
    for (int i = 0; i < arr1.size(); i++) {
        // Check if the current element in arr1 exists in arr2
        if (find(arr2.begin(), arr2.end(), arr1[i]) != arr2.end()) {
            common_elements.push_back(arr1[i]);
        }
    }

    // Second loop to search for remaining common elements in arr2
    for (int j = 0; j < arr2.size(); j++) {
        // Check if the current element in arr2 exists in arr1
        if (find(arr1.begin(), arr1.end(), arr2[j]) != arr1.end()) {
            common_elements.push_back(arr2[j]);
        }
    }

    // Sort the common elements for easy printing
    sort(common_elements.begin(), common_elements.end());

    return common_elements;
}

